import React, { useState, useEffect, useCallback } from 'react';
import { ProjectStatus } from './domain';
import { ProgressBar, StatusBadge } from './ui-components';
import { ProjectLogic } from './project-logic';
import { useNotificationService } from './ui-components';

// Internal helper for KPI calculation (simplified)
const calculateGlobalKpis = (projects) => {
  const activeProjects = projects.filter(p => p.status === ProjectStatus.ACTIVE).length;
  // totalEpics and completedStoriesThisWeek are mocked as per ISL constraints,
  // as the necessary logic/data (epicLogic, storyLogic) is not available in this component's context.
  const totalEpics = projects.reduce((sum, project) => sum + (project.id.length % 5 + 1), 0); // Mock value
  const completedStoriesThisWeek = projects.reduce((sum, project) => sum + (project.id.length % 3), 0); // Mock value
  return { activeProjects, totalEpics, completedStoriesThisWeek };
};

// Internal helper for generating year options
const getYearOptions = () => {
  const currentYear = new Date().getFullYear();
  const years = [];
  for (let i = 0; i < 3; i++) { // Current year and 2 previous years
    years.push(currentYear - i);
  }
  return years;
};

// Internal helper for generating project status options
const getProjectStatusOptions = () => {
  // ProjectStatus is an enum object, convert to array of values
  return Object.values(ProjectStatus);
};

export default function DashboardPresentation({ projectLogic, notificationService, onNavigateToProjectDetail, onAddNewProject }) {
  const [projects, setProjects] = useState([]);
  const [globalKpis, setGlobalKpis] = useState({ activeProjects: 0, totalEpics: 0, completedStoriesThisWeek: 0 });
  const [selectedStatus, setSelectedStatus] = useState(''); // Empty string for 'All'
  const [selectedYear, setSelectedYear] = useState(''); // Empty string for 'All'
  const [isLoading, setIsLoading] = useState(true);

  const fetchAndFilterProjects = useCallback(async () => {
    setIsLoading(true);
    try {
      const allProjects = await projectLogic.getAllProjects();

      let filtered = allProjects;

      if (selectedStatus) {
        filtered = filtered.filter(p => p.status === selectedStatus);
      }

      if (selectedYear) {
        const yearNum = parseInt(selectedYear, 10);
        filtered = filtered.filter(p => {
          const startDate = p.plannedStartDate ? new Date(p.plannedStartDate) : null;
          const endDate = p.plannedEndDate ? new Date(p.plannedEndDate) : null;
          return (startDate && startDate.getFullYear() === yearNum) || (endDate && endDate.getFullYear() === yearNum);
        });
      }

      setProjects(filtered);
      setGlobalKpis(calculateGlobalKpis(filtered));
    } catch (error) {
      console.error("Error fetching or filtering projects:", error);
      notificationService.ShowError("Failed to load projects. Please try again.");
      setProjects([]);
      setGlobalKpis({ activeProjects: 0, totalEpics: 0, completedStoriesThisWeek: 0 });
    } finally {
      setIsLoading(false);
    }
  }, [projectLogic, selectedStatus, selectedYear, notificationService]);

  useEffect(() => {
    fetchAndFilterProjects();
  }, [fetchAndFilterProjects]);

  const handleStatusChange = useCallback((e) => {
    setSelectedStatus(e.target.value);
  }, []);

  const handleYearChange = useCallback((e) => {
    setSelectedYear(e.target.value);
  }, []);

  const yearOptions = getYearOptions();
  const statusOptions = getProjectStatusOptions();

  return (
    <div className="p-6 bg-gray-100 min-h-screen">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-gray-800">Dashboard</h1>
        <button onClick={onAddNewProject} className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700">
          Add New Project
        </button>
      </div>

      {/* Global KPI Display */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
        <div className="bg-white p-4 rounded-lg shadow-md">
          <h2 className="text-lg font-semibold text-gray-700">Active Projects</h2>
          <p className="text-3xl font-bold text-blue-600">{globalKpis.activeProjects}</p>
        </div>
        <div className="bg-white p-4 rounded-lg shadow-md">
          <h2 className="text-lg font-semibold text-gray-700">Total Epics</h2>
          <p className="text-3xl font-bold text-purple-600">{globalKpis.totalEpics}</p>
        </div>
        <div className="bg-white p-4 rounded-lg shadow-md">
          <h2 className="text-lg font-semibold text-gray-700">Completed Stories This Week</h2>
          <p className="text-3xl font-bold text-green-600">{globalKpis.completedStoriesThisWeek}</p>
        </div>
      </div>

      {/* Filter Controls */}
      <div className="flex flex-wrap gap-4 mb-8 p-4 bg-white rounded-lg shadow-md">
        <div className="flex flex-col">
          <label htmlFor="status-filter" className="text-sm font-medium text-gray-700 mb-1">Filter by Status:</label>
          <select
            id="status-filter"
            className="p-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
            value={selectedStatus}
            onChange={handleStatusChange}
          >
            <option value="">All Statuses</option>
            {statusOptions.map(status => (
              <option key={status} value={status}>{status.replace(/_/g, ' ')}</option>
            ))}
          </select>
        </div>
        <div className="flex flex-col">
          <label htmlFor="year-filter" className="text-sm font-medium text-gray-700 mb-1">Filter by Year:</label>
          <select
            id="year-filter"
            className="p-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
            value={selectedYear}
            onChange={handleYearChange}
          >
            <option value="">All Years</option>
            {yearOptions.map(year => (
              <option key={year} value={year}>{year}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Project Cards */}
      {isLoading ? (
        <div className="text-center text-gray-600 text-lg">Loading projects...</div>
      ) : projects.length === 0 ? (
        <div className="text-center text-gray-600 text-lg">No projects found matching the selected criteria.</div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {projects.map(project => (
            <div
              key={project.id}
              className="bg-white p-6 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-200 cursor-pointer"
              onClick={() => onNavigateToProjectDetail(project.id)}
            >
              <div className="flex justify-between items-start mb-4">
                <h3 className="text-xl font-bold text-gray-900">{project.name}</h3>
                <StatusBadge status={project.status} />
              </div>
              <p className="text-gray-600 mb-2">Owner: {project.owner}</p>
              <div className="mb-4">
                <ProgressBar value={project.progress} />
              </div>
              <div className="text-sm text-gray-500">
                {/* These counts are placeholders as per ISL, not available in ProjectEntity */}
                <p>Total Epics: {project.id.length % 5 + 1}</p>
                <p>Overdue Epics: {project.id.length % 3}</p>
                <p>Blocked Epics: {project.id.length % 2}</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}